/// Parses a hex blob. `-` is the empty blob, as in the harness.
fn bytes(digits: &str) -> Vec<u8> {
    if digits == "-" {
        return Vec::new();
    }
    (0..digits.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&digits[i..i + 2], 16).unwrap())
        .collect()
}

/// Formats octets as lowercase hex, with `-` for the empty string.
fn hex(data: &[u8]) -> String {
    if data.is_empty() {
        return "-".to_string();
    }
    data.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn status_word(digits: &str) -> u32 {
    u32::from_str_radix(digits, 16).unwrap()
}

fn reply<T: std::fmt::Display>(result: Result<T, Error>) -> String {
    match result {
        Ok(value) => format!("ok {value}"),
        Err(error) => format!("err {}", error.code()),
    }
}

fn encode_value(kind: &str, value: &str) -> Vec<u8> {
    match kind {
        "bool" => encode::boolean(value.parse::<i32>().unwrap() != 0),
        "int" => encode::int(value.parse().unwrap()),
        "integer" => encode::integer(&bytes(value)),
        "octets" => encode::octets(&bytes(value)),
        _ => panic!("unknown encoder kind: {kind}"),
    }
}

/// `cap` is `-` for the size query, or the buffer size of the harness call.
fn encode_reply(encoded: &[u8], cap: &str) -> String {
    if cap == "-" {
        return format!("need={}", encode::write_to(encoded, None).unwrap());
    }
    let mut buf = vec![0u8; cap.parse().unwrap()];
    match encode::write_to(encoded, Some(&mut buf[..])) {
        Ok(written) => format!("ok {}", hex(&buf[..written])),
        Err(error) => format!("err {} need={}", error.code(), encoded.len()),
    }
}

fn decode_reply(kind: &str, digits: &str) -> String {
    let input = bytes(digits);
    match kind {
        "bool" => reply(decode::boolean(&input).map(i32::from)),
        "int" => reply(decode::int(&input)),
        "len" => reply(length::decode(&input)),
        "octets" => reply(decode::octets(&input).map(hex)),
        _ => panic!("unknown decoder kind: {kind}"),
    }
}

/// Runs one harness command and returns the reply line it prints.
fn replay(command: &str) -> String {
    let words: Vec<&str> = command.split(' ').collect();
    match words.as_slice() {
        ["enc", "len", len] => format!("ok {}", hex(&length::encode(len.parse().unwrap()))),
        ["enc", kind, value, cap] => encode_reply(&encode_value(kind, value), cap),
        ["dec", kind, digits] => decode_reply(kind, digits),
        ["conf", status] => format!(
            "ok 0x{:08x}",
            trust::status_to_confidence(status_word(status))
        ),
        ["error", status] => format!("ok 0x{:08x}", trust::status_to_error(status_word(status))),
        _ => panic!("unknown oracle command: {command}"),
    }
}

